function buildC1Lesson(slug: string): LessonData {
  const lessonDef = C1_LESSONS[slug as keyof typeof C1_LESSONS];
  if (!lessonDef) {
    throw new Error(`C1 lesson ${slug} not found`);
  }

  const slughyphen = slug.split("-");
  const order = parseInt(slughyphen[2]) || 1;

  const grammarSection: GrammarItem[] = [
    {
      title: "Advanced Subjunctive & Conditional Mastery",
      spainContent: `C1 Spanish requires mastery of the subjunctive in all tenses, conditional structures, and expressing nuance. Example: "Si no hubiera estado allí, no habría pasado nada."`,
      latamContent: `Mexican Spanish applies the same advanced structures, with regional variations in subjunctive usage in conversational speech. Mexicans may use indicative where other varieties use subjunctive.`,
      note: "C1 is about sophistication, nuance, and control of complex structures.",
    },
    {
      title: `${lessonDef.title} at C1 Level`,
      spainContent: `${lessonDef.title} at C1 level requires not just vocabulary but cultural understanding, register awareness, and nuance in expression. Context determines meaning.`,
      latamContent: `In Mexico and Latin America, ${lessonDef.title} is understood through the lens of Mexican culture, values, and ways of communicating.`,
      note: "C1 speakers recognize subtlety, irony, and multiple layers of meaning.",
    },
  ];

  const dialogues: DialogueScenario[] = [];

  for (let i = 0; i < 3; i++) {
    dialogues.push({
      id: `dialogue-spain-${i + 1}`,
      title: `${lessonDef.title} - Scene ${i + 1} (Spain)`,
      region: "SPAIN",
      setting: `Madrid/Barcelona setting for ${lessonDef.title}`,
      lines: [
        { speaker: "Ana", text: lessonDef.vocabulary[i]?.exampleSentenceSpain || `Hablando de ${lessonDef.title}... (Spain ${i + 1})`, region: "SPAIN", setting: `Madrid/Barcelona setting for ${lessonDef.title}` },
        { speaker: "Carlos", text: lessonDef.vocabulary[(i + 1) % lessonDef.vocabulary.length]?.exampleSentenceSpain || `Claro, en España... (Spain ${i + 1})`, region: "SPAIN", setting: `Madrid/Barcelona setting for ${lessonDef.title}` },
        { speaker: "Ana", text: `Exactamente. (Spain ${i + 1})`, region: "SPAIN", setting: `Madrid/Barcelona setting for ${lessonDef.title}` },
      ],
    });
  }

  for (let i = 0; i < 3; i++) {
    dialogues.push({
      id: `dialogue-latam-${i + 1}`,
      title: `${lessonDef.title} - Scene ${i + 1} (Mexico)`,
      region: "LATAM",
      setting: `Mexico City/Guadalajara setting for ${lessonDef.title}`,
      lines: [
        { speaker: "María", text: lessonDef.vocabulary[i]?.exampleSentenceLatam || `Oye, ${lessonDef.title.toLowerCase()}... (Mexico ${i + 1})`, region: "LATAM", setting: `Mexico City/Guadalajara setting for ${lessonDef.title}` },
        { speaker: "Diego", text: lessonDef.vocabulary[(i + 1) % lessonDef.vocabulary.length]?.exampleSentenceLatam || `Sí, aquí en México... (Mexico ${i + 1})`, region: "LATAM", setting: `Mexico City/Guadalajara setting for ${lessonDef.title}` },
        { speaker: "María", text: `Neta, eso es verdad. (Mexico ${i + 1})`, region: "LATAM", setting: `Mexico City/Guadalajara setting for ${lessonDef.title}` },
      ],
    });
  }

  const quiz: QuizQuestion[] = [
    {
      questionId: "q1",
      type: "multiple-choice",
      questionText: `What is the focus of C1-level Spanish?`,
      options: ["Basic vocabulary", "Nuance, sophistication, and register awareness", "Greeting phrases", "Simple past tense only"],
      correctAnswer: "Nuance, sophistication, and register awareness",
      explanation: "C1 is about expressing complex ideas with sophistication and understanding subtlety in language and culture.",
    },
    {
      questionId: "q2",
      type: "multiple-choice",
      questionText: `How does context affect ${lessonDef.title} at C1 level?`,
      options: ["Context doesn't matter", "Context completely determines meaning", "Only formal context matters", "Only casual context matters"],
      correctAnswer: "Context completely determines meaning",
      explanation: "At C1, the same expression can have completely different meanings depending on tone, audience, and context.",
    },
    {
      questionId: "q3",
      type: "multiple-choice",
      questionText: `What is register awareness?`,
      options: ["Speaking in one style only", "Knowing when to shift between formal, neutral, and casual Spanish", "Avoiding Spanish entirely", "Using only slang"],
      correctAnswer: "Knowing when to shift between formal, neutral, and casual Spanish",
      explanation: "Register awareness is the ability to adjust your Spanish based on the situation, audience, and context.",
    },
    {
      questionId: "q4",
      type: "multiple-choice",
      questionText: `Why is cultural understanding important at C1?`,
      options: ["It's not important", "Language and culture are inseparable; understanding culture is understanding language", "Culture is only for academics", "Only Spain has culture"],
      correctAnswer: "Language and culture are inseparable; understanding culture is understanding language",
      explanation: "At C1, you recognize that Spanish in Mexico is different from Spanish in Spain, not just in vocabulary but in values and ways of thinking.",
    },
    {
      questionId: "q5",
      type: "multiple-choice",
      questionText: `What is mastery at C1?`,
      options: ["Memorizing lists of words", "Understanding nuance, controlling complex structures, and adapting to context", "Speaking quickly", "Knowing every dictionary word"],
      correctAnswer: "Understanding nuance, controlling complex structures, and adapting to context",
      explanation: "C1 mastery is about understanding what isn't said, expressing complexity, and knowing exactly which form is appropriate for each situation.",
    },
  ];

  const flashcards: FlashcardItem[] = lessonDef.vocabulary.map((v, idx) => ({
    id: `fc-${slug}-${idx + 1}`,
    frontSpain: v.spainVariant,
    frontLatam: v.latamVariant,
    backEnglish: v.english,
    variantDifferenceNote: v.spainVariant !== v.latamVariant ? `Spain: "${v.spainVariant}", Mexico: "${v.latamVariant}"` : "Same in both regions",
    exampleSentenceSpain: v.exampleSentenceSpain || "",
    exampleSentenceLatam: v.exampleSentenceLatam || "",
    partOfSpeech: v.partOfSpeech,
  }));

  return {
    id: `lesson-${slug}`,
    slug,
    title: lessonDef.title,
    description: lessonDef.description,
    level: "C1",
    difficulty: "ADVANCED",
    order,
    imageUrl: null,
    durationMinutes: 40,
    isPublished: true,
    vocabularyTable: lessonDef.vocabulary,
    grammarSection,
    dialogues,
    quiz,
    flashcards,
    vocabularyJson: lessonDef.vocabulary.map((v) => ({
      word: v.word,
      translation: `${v.spainVariant} / ${v.latamVariant}`,
      partOfSpeech: v.partOfSpeech,
      example: v.exampleSentenceLatam,
    })),
    grammarJson: grammarSection.map((g) => ({
      title: g.title,
      content: `${g.spainContent} | ${g.latamContent}`,
    })),
    content: `# ${lessonDef.title}\n\n${lessonDef.description}\n\nAt C1 level, this topic is not just about vocabulary—it's about understanding the deep nuances of Mexican and Spanish Spanish, recognizing cultural values embedded in language, and knowing exactly when and how to shift your register.`,
  };
}

export function generateC1Lessons(): LessonData[] {
  const c1Slugs = Object.keys(C1_LESSONS);
  return c1Slugs.map((slug) => buildC1Lesson(slug));
}